+# SPDX-License-Identifier: Apache-2.0
+
 import pytest
 import torch

@@ -132,3 +134,55 @@ def test_fused_rms_norm_quant(
                                out_quant.to(dtype=torch.float32),
                                atol=1e-3,
                                rtol=1e-3)
+
+
+@pytest.mark.parametrize("num_tokens", NUM_TOKENS)
+@pytest.mark.parametrize("hidden_size", HIDDEN_SIZES)
+@pytest.mark.parametrize("dtype", DTYPES)
+@pytest.mark.parametrize("seed", SEEDS)
+@pytest.mark.parametrize("device", CUDA_DEVICES)
+@torch.inference_mode()
+def test_rms_norm_strided_input(
+    num_tokens: int,
+    hidden_size: int,
+    dtype: torch.dtype,
+    seed: int,
+    device: str,
+) -> None:
+    """Test RMS norm with strided input (non-contiguous memory layout).
+
+    This simulates the case where we have a fused QKV projection and want
+    to apply layernorm to only the Q part, which has a stride larger than
+    hidden_size.
+    """
+    current_platform.seed_everything(seed)
+    torch.set_default_device(device)
+
+    # Create a larger tensor that simulates fused QKV output
+    # with stride = hidden_size * 3 for each token
+    stride_factor = 3
+    full_size = num_tokens * hidden_size * stride_factor
+    full_tensor = torch.randn(full_size, dtype=dtype).reshape(
+        num_tokens, hidden_size * stride_factor)
+
+    # Extract only the first hidden_size elements (simulating Q from QKV)
+    # This creates a strided view where stride != hidden_size
+    strided_input = full_tensor[:, :hidden_size]
+
+    # Create a contiguous copy for reference
+    contiguous_input = strided_input.contiguous()
+
+    # Weight for layernorm
+    weight = torch.empty(hidden_size, dtype=dtype).normal_(mean=1.0, std=0.1)
+    epsilon = 1e-6
+
+    # Outputs
+    out_strided = torch.empty_like(strided_input)
+    out_contiguous = torch.empty_like(contiguous_input)
+
+    # Apply layernorm to both
+    torch.ops._C.rms_norm(out_strided, strided_input, weight, epsilon)
+    torch.ops._C.rms_norm(out_contiguous, contiguous_input, weight, epsilon)
+
+    # Results should be the same
+    torch.testing.assert_close(out_strided, out_contiguous, atol=1e-5, rtol=1e-5)

