@@ -147,3 +147,112 @@ void dynamic_per_token_scaled_fp8_quant(
                 hidden_size);
       });
 }
+
+namespace vllm {
+
+template <typename scalar_t>
+__global__ void dynamic_per_token_scaled_fp8_quant_with_layernorm_kernel(
+    FP8_TYPE* __restrict__ out, float* __restrict__ scale,
+    scalar_t const* __restrict__ input, const int64_t input_stride,
+    scalar_t const* __restrict__ weight, float const* __restrict__ scale_ub,
+    const float epsilon, const int hidden_size) {
+  float const min_scaling_factor = 1.0f / (FP8_E4M3_MAX * 512.f);
+
+  int const tid = threadIdx.x;
+  int const token_idx = blockIdx.x;
+
+  // Use int64 to avoid overflowing an int32 when calculating this offset
+  int64_t offset = static_cast<int64_t>(token_idx) * input_stride;
+  scalar_t const* __restrict__ token_input = &input[offset];
+  FP8_TYPE* __restrict__ token_output = &out[token_idx * hidden_size];
+
+  // First pass: compute layernorm variance
+  __shared__ float s_variance;
+  float variance = 0.0f;
+
+  for (int idx = tid; idx < hidden_size; idx += blockDim.x) {
+    const float x = static_cast<float>(token_input[idx]);
+    variance += x * x;
+  }
+
+  using BlockReduce = cub::BlockReduce<float, 1024>;
+  __shared__ typename BlockReduce::TempStorage reduceStorage;
+  variance = BlockReduce(reduceStorage).Reduce(variance, cub::Sum{}, blockDim.x);
+
+  if (tid == 0) {
+    s_variance = rsqrtf(variance / hidden_size + epsilon);
+  }
+  __syncthreads();
+
+  // Second pass: apply layernorm, compute absmax, and quantize
+  bool const can_vectorize = hidden_size % 4 == 0;
+  float absmax_val = 0.0f;
+
+  if (can_vectorize) {
+    // Vectorized path - compute normalized values and track absmax
+    for (int i = tid; i < hidden_size; i += blockDim.x) {
+      float x = static_cast<float>(token_input[i]);
+      float normalized = (x * s_variance) * static_cast<float>(weight[i]);
+      absmax_val = max(absmax_val, fabs(normalized));
+    }
+  } else {
+    for (int i = tid; i < hidden_size; i += blockDim.x) {
+      float x = static_cast<float>(token_input[i]);
+      float normalized = (x * s_variance) * static_cast<float>(weight[i]);
+      absmax_val = max(absmax_val, fabs(normalized));
+    }
+  }
+
+  __shared__ typename BlockReduce::TempStorage reduceStorage2;
+  float const block_absmax_val_maybe =
+      BlockReduce(reduceStorage2).Reduce(absmax_val, cub::Max{}, blockDim.x);
+  __shared__ float token_scale;
+  if (tid == 0) {
+    if (scale_ub) {
+      token_scale = min(block_absmax_val_maybe, *scale_ub);
+    } else {
+      token_scale = block_absmax_val_maybe;
+    }
+    // token scale computation
+    token_scale = max(token_scale / FP8_E4M3_MAX, min_scaling_factor);
+    scale[token_idx] = token_scale;
+  }
+  __syncthreads();
+
+  // Third pass: apply layernorm and quantize
+  for (int i = tid; i < hidden_size; i += blockDim.x) {
+    float x = static_cast<float>(token_input[i]);
+    float normalized = (x * s_variance) * static_cast<float>(weight[i]);
+    token_output[i] =
+        scaled_fp8_conversion<false>(normalized, token_scale);
+  }
+}
+
+}  // namespace vllm
+
+void dynamic_per_token_scaled_fp8_quant_with_layernorm(
+    torch::Tensor& out,          // [..., d]
+    torch::Tensor const& input,  // [..., d]
+    torch::Tensor const& weight,  // [d]
+    torch::Tensor& scales,
+    std::optional<at::Tensor> const& scale_ub, double epsilon) {
+  int const hidden_size = input.size(-1);
+  int const num_tokens = input.numel() / hidden_size;
+  int64_t const input_stride = input.stride(-2);
+  dim3 const grid(num_tokens);
+  dim3 const block(std::min(hidden_size, 1024));
+
+  const at::cuda::OptionalCUDAGuard device_guard(device_of(input));
+  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
+  VLLM_DISPATCH_FLOATING_TYPES(
+      input.scalar_type(),
+      "dynamic_per_token_scaled_fp8_quant_with_layernorm_kernel", [&] {
+        vllm::dynamic_per_token_scaled_fp8_quant_with_layernorm_kernel<
+            scalar_t><<<grid, block, 0, stream>>>(
+            out.data_ptr<FP8_TYPE>(), scales.data_ptr<float>(),
+            input.data_ptr<scalar_t>(), input_stride,
+            weight.data_ptr<scalar_t>(),
+            scale_ub.has_value() ? scale_ub->data_ptr<float>() : nullptr,
+            epsilon, hidden_size);
+      });
+}
